@tailwind base;
@layer base {
    /*
    You can extend base styles here. Most are reset through Preflight. More info here: https://tailwindcss.com/docs/preflight 

    h1 {
        @apply text-2xl;
    }
    h2 {
        @apply text-xl;
    }
    h3 {
        @apply text-lg;
    }
    a {
        @apply text-blue-600 underline;
    } */
    html,body {
        scroll-behavior: smooth;
    } 
    a {
        @apply text-info underline;
    }
    p {
        @apply text-gray-1;
    }
    th,tr{
        white-space: nowrap;
    }
}

